package br.com.admeclesial.infrastructure.configuration;
import br.com.admeclesial.domain.usuario.*; import br.com.admeclesial.infrastructure.persistence.usuario.*; import org.junit.jupiter.api.Test; import org.junit.jupiter.api.extension.ExtendWith; import org.mockito.Mock; import org.mockito.junit.jupiter.MockitoExtension; import java.lang.reflect.Field; import java.util.*; import static org.junit.jupiter.api.Assertions.*; import static org.mockito.Mockito.*;
@ExtendWith(MockitoExtension.class) class AdmEclesialUserDetailsServiceTest { @Mock UsuarioRepository usuarios; @Mock UsuarioPerfilRepository perfis; @Test void deveCarregarUsuarioComPerfis(){var u=new Usuario();u.setLogin("maria");u.setSenhaHash("hash");u.setAtivo(true);setId(u,1L);var p=new UsuarioPerfil();p.setUsuario(u);p.setPerfil(PerfilAcesso.SECRETARIA);when(usuarios.findByLoginIgnoreCase("maria")).thenReturn(Optional.of(u));when(perfis.findByUsuarioId(1L)).thenReturn(List.of(p));var details=new AdmEclesialUserDetailsService(usuarios,perfis).loadUserByUsername("maria");assertTrue(details.isEnabled());assertTrue(details.getAuthorities().stream().anyMatch(a->a.getAuthority().equals("ROLE_SECRETARIA")));} private static void setId(Usuario u,Long id){try{Field f=Usuario.class.getDeclaredField("id");f.setAccessible(true);f.set(u,id);}catch(Exception e){throw new RuntimeException(e);}} }
